def dfs(r, c):
    if not (0 <= r < m and 0 <= c < n and grid[r][c] == 1):
        return 0
    grid[r][c] = 0
    count = 1
    for i in range(4):
        nr, nc = r + DIR[i], c + DIR[i+1]
        if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 1:
            count += dfs(nr, nc)
    return count
